value.string:
{\n
  "type": "object",\n
  "additionalProperties": true,\n
  "description": "Result of updating an installed Business Template from the repository.",\n
  "properties": {\n
    "success": {\n
      "type": "boolean"\n
    },\n
    "operation": {\n
      "type": "string"\n
    },\n
    "business_template": {\n
      "type": "string"\n
    },\n
    "created": {\n
      "type": "array",\n
      "items": {\n
        "type": "string"\n
      }\n
    },\n
    "modified": {\n
      "type": "array",\n
      "items": {\n
        "type": "string"\n
      }\n
    },\n
    "deleted": {\n
      "type": "array",\n
      "items": {\n
        "type": "string"\n
      }\n
    },\n
    "revision": {\n
      "type": "string"\n
    },\n
    "error": {\n
      "type": "string"\n
    }\n
  }\n
}

{
 "type": "object",
 "additionalProperties": false,
 "required": [
 "business_template"
 ],
 "properties": {
 "business_template": {
 "type": "string",
 "description": "Bare directory name of the Business Template to update."
 },
 "update_catalog": {
 "type": [
 "boolean",
 "integer"
 ],
 "default": false,
 "description": "Whether to also update the catalog."
 },
 "reinstall": {
 "type": [
 "boolean",
 "integer"
 ],
 "default": false,
 "description": "Force a full reinstall rather than a diff/keep update."
 },
 "force": {
 "type": [
 "boolean",
 "integer"
 ],
 "default": false,
 "description": "Proceed even when both the repository and ERP5 changed the same objects (overwrites ERP5-side changes)."
 }
 }
 }
